#include <bits/stdc++.h>
using namespace std;

int main(void) {
	int n;
	priority_queue<long long, vector<long long>, greater<long long> >pq;
	long long x, y, l;
	long long ans = 0;

	cin >> n >> l;
	for (int i = 0; i < n; i++) {
		cin >> x;
		l -= x;
		pq.push(x);
	}

	if (l > 0) {
		pq.push(l);
		n++;
	}
	for (int i = 0; i < (n - 1); i++) {
		x = pq.top();
		pq.pop();
		y = pq.top();
		pq.pop();
		ans += x + y;
		pq.push(x + y);
	}

	cout << ans << endl;
	return 0;
}
